router.put('/lesson-plans/:id',async(request,response,next)=>{try{const d=request.body;const owner=await pool.query(`SELECT pl.id,pl.turma_id,pl.status FROM planejamentos_aula pl JOIN professores p ON p.id=pl.professor_id WHERE pl.id=$1 AND p.usuario_id=$2 AND pl.status IN('Rascunho','Correção solicitada')`,[request.params.id,request.access.userId]);if(!owner.rows[0])return response.status(409).json({message:'O planejamento não está disponível para edição.'});const link=await professorClass(request,d.turmaId||owner.rows[0].turma_id);if(!link)return response.status(403).json({message:'Turma não atribuída ao professor.'});const {rows}=await pool.query(`UPDATE planejamentos_aula SET turma_id=$1,componente_curricular=$2,data_aula=$3,bimestre=$4,quantidade_aulas=$5,tema=$6,objetivos=$7,habilidades_bncc=$8,conteudos=$9,metodologia=$10,recursos=$11,avaliacao=$12,adaptacoes_inclusivas=$13,tarefa_casa=$14,observacoes=$15,status='Rascunho',versao=versao+1,parecer_coordenacao=NULL,atualizado_em=NOW() WHERE id=$16 RETURNING id,status,versao`,[d.turmaId,link.componente_curricular,d.data,Number(d.bimestre),Number(d.quantidadeAulas),d.tema,d.objetivos,d.habilidadesBncc||null,d.conteudos,d.metodologia,d.recursos||null,d.avaliacao,d.adaptacoesInclusivas||null,d.tarefaCasa||null,d.observacoes||null,request.params.id]);await pool.query(`INSERT INTO historico_planejamentos_aula(planejamento_id,usuario_id,acao,status_anterior,status_novo,versao,dados) VALUES($1,$2,'EDITADO',$3,'Rascunho',$4,$5::jsonb)`,[request.params.id,request.access.userId,owner.rows[0].status,rows[0].versao,JSON.stringify({tema:d.tema,data:d.data,turmaId:d.turmaId})]);return response.json(rows[0]);}catch(error){return next(error);}});

